namespace ToneCustoms.ShellStudio.Core;
public sealed class WallOpeningService { public WallOpening Add(ShellProject project,SceneObject wall,float offset,float width,float height,float sill,bool door){if(wall.Type!=SceneObjectType.Wall)throw new ArgumentException("Opening target must be a wall");if(width<=0||height<=0||width>=wall.Scale.X)throw new ArgumentOutOfRangeException(nameof(width));sill=door?0:Math.Max(0,sill);if(sill+height>wall.Scale.Z)throw new ArgumentOutOfRangeException(nameof(height),"Opening exceeds wall height.");var half=width/2;offset=Math.Clamp(offset,half,wall.Scale.X-half);var left=offset-half;var right=offset+half;if(project.WallOpenings.Where(x=>x.WallId==wall.Id).Any(x=>left<x.Offset+x.Width/2&&right>x.Offset-x.Width/2))throw new InvalidOperationException("Opening overlaps an existing door or window.");var o=new WallOpening(wall.Id,offset,width,height,sill,door);project.WallOpenings.Add(o);return o;}public IEnumerable<WallOpening> ForWall(ShellProject p,Guid wall)=>p.WallOpenings.Where(x=>x.WallId==wall); }
